function draw(ctx, size) {
  ctx.imageSmoothingEnabled = false;
  const O = '#0d0a08', P1 = '#2a2620', P2 = '#4a443c', P3 = '#6a6358';
  const px = (x, y, w, h, c) => { ctx.fillStyle = c; ctx.fillRect(x|0, y|0, w|0, h|0); };
  px(0, 0, 32, 32, P1);
  for (let row = 0; row < 4; row++) {
    const y = row * 8;
    px(0, y, 32, 1, O);
    const off = row % 2 ? 4 : 0;
    for (let x = -off; x < 32; x += 8) {
      if (x >= 0) {
        px(x, y + 1, 7, 7, P2);
        px(x, y + 1, 3, 1, P3);
        px(x, y + 1, 1, 3, P3);
      }
    }
  }
  px(0, 0, 32, 1, O);
  px(0, 0, 1, 32, O);
  px(31, 0, 1, 32, O);
  px(0, 31, 32, 1, O);
  px(12, 10, 1, 6, P1);
  px(22, 18, 1, 8, P1);
}
